from slugify import slugify


def test_basic_slugify():
    assert slugify("Hello World") == "hello-world"


def test_special_characters_collapsed():
    assert slugify("  foo!!bar  ") == "foo-bar"


def test_already_lowercase_no_change():
    assert slugify("simple") == "simple"


def test_leading_trailing_hyphens_stripped():
    assert slugify("---hello---") == "hello"


def test_multiple_runs_become_single_hyphen():
    assert slugify("a   b---c") == "a-b-c"

